import { Link } from 'react-router-dom';
import type { LanguageCode, Word } from '@lexpad/core';
import { Bilingual } from '@/components/ui/Bilingual.js';
import { BoxMeter } from '@/components/ui/BoxMeter.js';
import { Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { nextCheck } from '@/features/schedule/nextCheck.js';
import { HOW_FOCUS, settingsPath } from '@/features/settings/paths.js';
import type { WordMove } from '@/features/session/useSession.js';
import { NEXT_WORDS_LISTED } from './tips.js';
import styles from './WhatNext.module.css';

/**
 * "What happens next" on a session summary (the new learner's journey, M4):
 * the most important lesson of the app has just happened — each word moved
 * up a box or back, and comes back on a day Lexpad chose — and until this
 * nothing said so. Worked out from the session's own answers, no read.
 *
 * `full` names each word (up to five) with its box, where it went and its
 * next check, or counts them above five; `short` is one line for a learner
 * who has seen the full block a few times.
 */
export function WhatNext({
  mode,
  moves,
  today,
  langOf,
}: {
  mode: 'full' | 'short';
  moves: readonly WordMove[];
  today: number;
  /** The language each headword is written in (its own notebook's). */
  langOf: (word: Word) => LanguageCode;
}): React.JSX.Element | null {
  if (moves.length === 0) return null;

  if (mode === 'short') {
    const tomorrow = moves.filter((move) => !move.kept && move.dueDay === today + 1).length;
    if (tomorrow === 0) return null;
    return <p className={styles.short}>{t('summary.nextShort', { count: tomorrow })}</p>;
  }

  const listed = moves.length <= NEXT_WORDS_LISTED;
  const movedUp = moves.filter((move) => !move.kept && move.to > move.from).length;
  const backToday = moves.filter((move) => !move.kept && move.dueDay <= today).length;

  return (
    <section className={styles.section} aria-labelledby="what-next-title">
      <h2 id="what-next-title" className={styles.title}>
        {t('summary.nextTitle')}
      </h2>
      <div className={styles.card}>
        {listed ? (
          <ul className={cx(styles.list, moves.length > 3 && styles.listWide)}>
            {moves.map((move) => (
              <li key={move.word.id} className={styles.row}>
                <BoxMeter box={move.to} className={styles.meter} />
                <span className={styles.text}>
                  <span className={styles.head}>
                    <Bilingual lang={langOf(move.word)} className={styles.word}>
                      {move.word.headword}
                    </Bilingual>
                    <span className={styles.move}>{moveLine(move)}</span>
                  </span>
                  <span className={styles.when}>
                    {move.dueDay <= today ? t('summary.nextToday') : nextCheck(move, today).text}
                  </span>
                </span>
              </li>
            ))}
          </ul>
        ) : (
          <div className={styles.counts}>
            {movedUp > 0 && <p className={styles.count}>{t('summary.movedUp', { count: movedUp })}</p>}
            {backToday > 0 && (
              <p className={styles.count}>{t('summary.comeBackToday', { count: backToday })}</p>
            )}
          </div>
        )}
        <p className={styles.foot}>
          <span className={styles.footText}>{t('summary.nextLine')}</span>
          <Link to={`${settingsPath('how')}#${HOW_FOCUS.boxes}`} className={styles.how}>
            {t('summary.nextHow')}
            <Icon name="chevronRight" size={14} weight={2.2} className={styles.go} />
          </Link>
        </p>
      </div>
    </section>
  );
}

/** Where a word went: up, back, or nowhere (kept as practice, or a miss already in box 1). */
function moveLine(move: WordMove): string {
  if (move.kept || move.to === move.from) return t('summary.nextStay', { box: move.to });
  return move.to > move.from
    ? t('summary.nextUp', { box: move.to })
    : t('summary.nextBack', { box: move.to });
}
