import { useEffect, useRef, useState } from 'react';
import { cx } from '@/lib/cx.js';
import { prefersReducedMotion } from './motionPrefs.js';
import styles from './CountUp.module.css';

/** How long a count takes: `--dur-count` in tokens.css, which JavaScript cannot read for free. */
const COUNT_MS = 700;

/** Ease-out, so the count slows as it lands rather than stopping dead. */
function easeOut(progress: number): number {
  return 1 - (1 - progress) ** 3;
}

/**
 * A number that counts up from `from` to `value` once, when it first shows
 * or when `value` changes. The final value is what a screen reader hears
 * (`label`, or the number itself); the moving digits are hidden from it.
 * A change of one does not count, it pops: 4 → 5 is not a journey. Under
 * reduced motion, in a hidden tab, or for a number that went down, the
 * final value is drawn at once. No frame is requested once it has landed.
 */
export function CountUp({
  value,
  from = 0,
  label,
  className,
  format = String,
}: {
  value: number;
  from?: number;
  /** What a screen reader hears; the final value is in it. */
  label?: string;
  className?: string | undefined;
  format?: (n: number) => string;
}): React.JSX.Element {
  const [instant] = useState(() => still(from, value));
  const [shown, setShown] = useState(from);
  const popped = value - from === 1;
  const frame = useRef<number | undefined>(undefined);

  useEffect(() => {
    if (instant) return;
    const start = performance.now();
    const step = (now: number): void => {
      if (document.hidden) {
        setShown(value);
        return;
      }
      const progress = Math.min(1, (now - start) / COUNT_MS);
      setShown(Math.round(from + (value - from) * easeOut(progress)));
      if (progress < 1) frame.current = requestAnimationFrame(step);
    };
    frame.current = requestAnimationFrame(step);
    return () => {
      if (frame.current !== undefined) cancelAnimationFrame(frame.current);
    };
  }, [instant, from, value]);

  return (
    <span
      className={cx(styles.count, popped && styles.pop, className)}
      aria-label={label ?? format(value)}
      role="img"
    >
      <span aria-hidden="true">{format(instant ? value : shown)}</span>
    </span>
  );
}

/** Whether the number simply appears: no distance to count, or nobody wants it counted. */
function still(from: number, value: number): boolean {
  return value - from <= 1 || prefersReducedMotion();
}
