import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import {
  type CardType,
  type Deck,
  type LanguageCode,
  KINDS,
  type Kind,
  type PracticeScope,
} from '@lexpad/core';
import { Button } from '@/components/ui/Button.js';
import { EmptyState } from '@/components/ui/EmptyState.js';
import { Screen } from '@/components/layout/Screen.js';
import { NoteSheet } from '@/components/ui/NoteSheet.js';
import { Sheet } from '@/components/ui/Sheet.js';
import { WordDetail } from '@/features/word/WordDetail.js';
import { Spinner } from '@/components/ui/Spinner.js';
import { BoxMeter } from '@/components/ui/BoxMeter.js';
import { Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { getActiveNotebook, listNotebooks, loadSettings } from '@/db/repo.js';
import { getMeta } from '@/db/schema.js';
import { ChoiceCard } from './cards/ChoiceCard.js';
import { FlipCard } from './cards/FlipCard.js';
import { SpellCard } from './cards/SpellCard.js';
import { isChoice, isTyped } from './build.js';
import { useSession, type DeckScope, type SessionState } from './useSession.js';
import { Summary } from './Summary.js';
import { localDay, startTipSession } from '@/features/learn/state.js';
import { pickTip, type TipId } from '@/features/learn/tips.js';
import { useHeldTip, useLearn } from '@/features/learn/useLearn.js';
import styles from './Session.module.css';

const DECKS: readonly Deck[] = [
  'daily',
  'audio',
  'starred',
  'struggling',
  'confusables',
  'tricky',
  'notebook',
  'group',
  'mine',
  'level',
  'topic',
  'kind',
];

function deckFrom(value: string | null): Deck {
  return DECKS.find((deck) => deck === value) ?? 'daily';
}

/**
 * The languages and preferences a session needs, read from local data.
 *
 * A session may draw from more than one notebook, and a card written in
 * German must not be read out in English, so the languages are looked up
 * per card rather than fixed once. The notebook being shown is the
 * fallback for a card whose own notebook has gone.
 */
async function loadContext(): Promise<{
  targetLang: LanguageCode;
  meaningLang: LanguageCode;
  autoSpeak: boolean;
  speakExamples: boolean;
  /** Whether this client shows the SRS v2 screens (meta `srs`). */
  srs: boolean;
  byNotebook: Record<string, { targetLang: LanguageCode; meaningLang: LanguageCode }>;
}> {
  const [notebook, settings, all, srs] = await Promise.all([
    getActiveNotebook(),
    loadSettings(),
    listNotebooks(),
    getMeta('srs'),
  ]);
  return {
    targetLang: notebook?.targetLang ?? 'en',
    meaningLang: notebook?.meaningLang ?? 'fa',
    autoSpeak: settings?.autoSpeak ?? false,
    speakExamples: settings?.speakExamples ?? false,
    srs: srs?.state?.enabled === true,
    byNotebook: Object.fromEntries(
      all.map((one) => [one.id, { targetLang: one.targetLang, meaningLang: one.meaningLang }]),
    ),
  };
}

const DEFAULT_CONTEXT = {
  targetLang: 'en' as LanguageCode,
  meaningLang: 'fa' as LanguageCode,
  autoSpeak: false,
  speakExamples: false,
  srs: false,
  byNotebook: {} as Record<string, { targetLang: LanguageCode; meaningLang: LanguageCode }>,
};

/**
 * The practice session: one card at a time, graded by pointer, keyboard or
 * swipe. It owns the whole viewport, with no tab bar to press by accident.
 */
export function Session(): React.JSX.Element {
  const [params] = useSearchParams();
  const navigate = useNavigate();
  const deck = deckFrom(params.get('deck'));
  // Memoised: a fresh array on every render would rebuild the queue on
  // every render, and the queue is what the render is showing.
  const groupIds = useMemo(() => params.get('ids')?.split(',').filter(Boolean), [params]);
  // A token the summary's "Keep going" puts in the address to ask for this
  // deck again. It rides into the shuffle seed, so a second run of the same
  // deck is not the same run twice.
  const again = params.get('again') ?? '';
  // What a level, topic or kind deck practises; read once per URL.
  const scope = useMemo<DeckScope>(() => {
    const level = params.get('level');
    const topic = params.get('topic');
    const kind = params.get('kind');
    return {
      ...(level ? { level } : {}),
      ...(topic ? { topic } : {}),
      ...(kind && (KINDS as readonly string[]).includes(kind) ? { kind: kind as Kind } : {}),
    };
  }, [params]);

  const context = useLiveQuery(loadContext, DEFAULT_CONTEXT, []);
  // Which notebooks this session draws from. It rides in the address, so
  // the choice survives a reload and the back button, and Today decides it
  // from the setting before sending anybody here.
  const across: PracticeScope = params.get('scope') === 'all' ? 'all' : 'notebook';
  const { state, answer, answerTyped, answerChoice, next, undo, toggleStar, saveNote } = useSession(
    deck,
    groupIds,
    scope,
    across,
    again,
  );
  const { card, outcome, boxAfter, practised } = state;

  const [flipped, setFlipped] = useState(false);
  const [noteOpen, setNoteOpen] = useState(false);
  const [detailOpen, setDetailOpen] = useState(false);
  const [typed, setTyped] = useState('');

  const leave = useCallback((): void => {
    void navigate('/', { replace: true });
  }, [navigate]);

  /**
   * Advances and puts the next card face down.
   *
   * The typed answer is cleared here too. It used to survive into the next
   * card, so somebody who spelled one word found it already filled in on
   * the following one — and could grade a card against the previous word's
   * letters without noticing.
   */
  const advance = useCallback((): void => {
    setFlipped(false);
    setTyped('');
    next();
  }, [next]);

  // The new learner's journey (SRS v2): one quiet line on a card at three
  // moments — under the first flips, at the first miss, at the first answer
  // kept as practice. Never a modal, never while typing.
  const tip = useCardTip(state, flipped);

  // A graded card advances on its own, so the rhythm of a session holds
  // without the learner having to press anything. A line said about this
  // answer gets the time to be read.
  useEffect(() => {
    if (outcome === undefined) return;
    const timer = window.setTimeout(
      advance,
      tip !== undefined ? TIP_READ_MS : outcome === 'correct' ? 700 : 1600,
    );
    return () => {
      window.clearTimeout(timer);
    };
  }, [outcome, advance, tip]);

  // The prototype's keys: space flips, arrows grade, 1 to 4 pick, Enter
  // continues, S stars, Escape closes.
  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent): void => {
      if (noteOpen) return;
      const target = event.target;
      const typing = target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement;

      if (event.key === 'Escape') {
        leave();
        return;
      }

      // Enter submits the spelling drill from inside the field, which is
      // where the hands already are.
      if (typing && event.key === 'Enter' && card && isTyped(card.type)) {
        event.preventDefault();
        if (outcome === undefined) void answerTyped(typed);
        else advance();
        return;
      }
      if (typing) return;

      if (event.key === 's' || event.key === 'S') {
        event.preventDefault();
        void toggleStar();
        return;
      }
      if (!card) return;

      if (event.key === 'Enter' && outcome !== undefined) {
        event.preventDefault();
        advance();
        return;
      }
      if (isChoice(card.type)) {
        const index = Number.parseInt(event.key, 10) - 1;
        const option = card.options?.[index];
        if (option && outcome === undefined) {
          event.preventDefault();
          void answerChoice(option);
        }
        return;
      }
      if (isTyped(card.type)) return;

      if (event.key === ' ') {
        event.preventDefault();
        setFlipped(true);
        return;
      }
      if (outcome === undefined && flipped) {
        if (event.key === 'ArrowLeft') {
          event.preventDefault();
          void answer(false);
        } else if (event.key === 'ArrowRight') {
          event.preventDefault();
          void answer(true);
        }
      }
    };
    window.addEventListener('keydown', onKeyDown);
    return () => {
      window.removeEventListener('keydown', onKeyDown);
    };
  }, [
    advance,
    answer,
    answerChoice,
    answerTyped,
    card,
    flipped,
    leave,
    noteOpen,
    outcome,
    toggleStar,
    typed,
  ]);

  if (state.status === 'loading') {
    return (
      <Screen full>
        <Spinner />
      </Screen>
    );
  }

  if (state.status === 'empty') {
    return (
      <Screen full>
        <EmptyState
          middle
          icon="check"
          title={t('session.clearTitle')}
          body={t('today.nothingDue')}
          actions={<Button onClick={leave}>{t('action.done')}</Button>}
        />
      </Screen>
    );
  }

  if (state.status === 'finished' || !card) {
    return (
      <Summary
        summary={state.summary}
        context={context}
        onDone={leave}
        deck={deck}
        remaining={state.remaining}
        srs={context.srs}
      />
    );
  }

  const progress = state.total === 0 ? 0 : (state.done / state.total) * 100;
  // This card's own languages. A session may draw from more than one
  // notebook, and a German word must not be shown right-to-left or read
  // out in English because the notebook on screen happens to be Persian.
  const languages = context.byNotebook[card.word.notebookId] ?? context;
  const starred = card.word.progress?.starred === true;
  const hasCorrection = (card.word.correction ?? '') !== '';
  // A deck other than the day's plan is extra practice. When the card's
  // notebook keeps extra practice out of the schedule, a word that is not
  // due yet keeps its box, and the session says so up front (SRS v2) --
  // only when the deck has such a word: on a deck of due words every answer
  // counts, and the line read as if none would.
  const extraPractice =
    context.srs &&
    deck !== 'daily' &&
    state.schedules[card.word.notebookId]?.extraPractice === 'keep' &&
    state.notDue.has(card.word.notebookId);

  return (
    <main className={styles.screen}>
      <h1 className="sr-only">{t('session.heading')}</h1>
      <div className={styles.topBar}>
        <button type="button" className={styles.close} onClick={leave} aria-label={t('action.close')}>
          <Icon name="close" size={18} weight={2} />
        </button>
        <div
          className={styles.track}
          role="progressbar"
          aria-valuenow={state.done}
          aria-valuemax={state.total}
          aria-label={t('session.progress', { done: state.done, total: state.total })}
        >
          <div className={styles.fill} style={{ width: `${String(progress)}%` }} />
        </div>
        <span className={styles.counter}>
          {state.index + 1}/{state.total}
        </span>
      </div>

      <div className={styles.meta}>
        {/* Chips rather than a run-on sentence: three unrelated facts joined
            by middots read as one long label and none of them was legible
            at a glance. */}
        <span className={styles.metaChips}>
          <span className={cx(styles.chip, styles.chipKind)}>{typeLabel(card.type)}</span>
          {/* The ladder, made visible. Until the card is graded it shows the
              rung the word is on; the moment it is, it moves to the rung the
              word landed on and the new bar lights. This is the model the
              whole app runs on and it used to happen entirely out of sight. */}
          <BoxMeter
            key={boxAfter === undefined ? 'box' : `box-${String(boxAfter)}`}
            box={boxAfter ?? card.box}
            rung={boxAfter !== undefined && boxAfter > card.box}
            className={cx(
              styles.boxChip,
              boxAfter !== undefined && boxAfter > card.box && styles.boxUp,
              boxAfter !== undefined && boxAfter < card.box && styles.boxBack,
            )}
          />
          {/* Practice only: the box did not move, so nothing claims a rung.
              The tag is the whole feedback, and it is read out. */}
          {practised && (
            <span className={cx(styles.tag, styles.tagPractice)} role="status">
              <span className={styles.dot} />
              {t('schedule.practiceTag')}
            </span>
          )}
          {card.word.level !== undefined && <span className={styles.chip}>{card.word.level}</span>}
          {card.isNew && (
            <span className={cx(styles.tag, styles.tagNew)}>
              <span className={styles.dot} />
              {t('session.new')}
            </span>
          )}
          {hasCorrection && (
            <span className={cx(styles.tag, styles.tagCorrection)}>
              <span className={styles.dot} />
              {t('session.correction')}
            </span>
          )}
        </span>
        {extraPractice && <p className={styles.deckLine}>{t('schedule.deckLine')}</p>}
        <div className={styles.metaActions}>
          <div className={styles.undoSlot}>
            {state.canUndo && (
              <button
                type="button"
                className={styles.undo}
                onClick={() => {
                  void undo();
                }}
              >
                <Icon name="undo" size={14} weight={2} />
                {t('action.undo')}
              </button>
            )}
          </div>
          <button
            type="button"
            className={styles.metaButton}
            onClick={() => {
              setNoteOpen(true);
            }}
            aria-label={t('session.addNote')}
          >
            <Icon name="note" size={18} weight={1.9} />
          </button>
          <button
            type="button"
            className={cx(styles.metaButton, styles.starButton, starred && styles.starOn)}
            aria-label={starred ? t('action.unstar') : t('session.starWord')}
            aria-pressed={starred}
            onClick={() => {
              void toggleStar();
            }}
          >
            <Icon name={starred ? 'starOn' : 'star'} size={20} />
          </button>
          <button
            type="button"
            className={styles.metaButton}
            aria-label={t('session.details')}
            onClick={() => {
              setDetailOpen(true);
            }}
          >
            <Icon name="notebook" size={18} weight={2} />
          </button>
        </div>
      </div>

      {/* What this card is asking, as a heading above it. It used to sit
          under the answers as grey hint text, which is where nobody looks
          first and the last place an instruction should be. */}
      <h1 className={styles.ask}>{askFor(card.type)}</h1>

      <div className={styles.stage}>
        <SwipeArea
          enabled={!isChoice(card.type) && !isTyped(card.type) && flipped && outcome === undefined}
          onLeft={() => {
            void answer(false);
          }}
          onRight={() => {
            void answer(true);
          }}
        >
          {isTyped(card.type) ? (
            <SpellCard
              key={card.key}
              card={card}
              targetLang={languages.targetLang}
              meaningLang={languages.meaningLang}
              outcome={outcome}
              revealed={state.revealed}
              typed={typed}
              onType={setTyped}
              alt={state.index % 2 === 1}
            />
          ) : isChoice(card.type) ? (
            <ChoiceCard
              key={card.key}
              card={card}
              targetLang={languages.targetLang}
              meaningLang={languages.meaningLang}
              outcome={outcome}
              autoSpeak={context.autoSpeak}
              onChoose={(option) => {
                void answerChoice(option);
              }}
              alt={state.index % 2 === 1}
            />
          ) : (
            <FlipCard
              key={card.key}
              card={card}
              targetLang={languages.targetLang}
              meaningLang={languages.meaningLang}
              autoSpeak={context.autoSpeak}
              speakExamples={context.speakExamples}
              flipped={flipped}
              onFlip={() => {
                setFlipped(true);
              }}
              onEditMemo={() => {
                setNoteOpen(true);
              }}
              alt={state.index % 2 === 1}
            />
          )}
        </SwipeArea>
      </div>

      <div className={styles.actions}>
        {/* Above the buttons, which stay where they are: the action row grows
            upward into the stage. Read out by the status line below. */}
        {tip !== undefined && (
          <p className={styles.tipLine} aria-hidden="true">
            {t(`tip.${tip}`)}
          </p>
        )}
        {/* Keyed with the card so the buttons arrive with it, not ahead of it. */}
        <div key={card.key} className={cx(styles.actionsIn, state.index % 2 === 1 && styles.actionsInB)}>
          {isTyped(card.type) ? (
            <button
              type="button"
              className={cx(styles.primary, styles.accent)}
              disabled={typed.trim() === '' && outcome === undefined}
              onClick={() => {
                if (outcome === undefined) void answerTyped(typed);
                else advance();
              }}
            >
              {outcome === undefined ? t('session.check') : t('action.continue')}
            </button>
          ) : isChoice(card.type) ? (
            outcome === undefined ? (
              // The instruction is the heading above the card now.
              <div className={styles.hint} />
            ) : outcome === 'wrong' ? (
              // A wrong pick reveals the answer, and the learner decides when
              // they have read it; a right one moves on by itself.
              <button type="button" className={styles.primary} onClick={advance}>
                {t('action.continue')}
              </button>
            ) : (
              <div className={styles.hint} />
            )
          ) : !flipped ? (
            <button
              type="button"
              className={styles.primary}
              onClick={() => {
                setFlipped(true);
              }}
            >
              {t('session.showAnswer')}
            </button>
          ) : (
            // After a grade the two buttons stay where they were, the chosen
            // one filled in, until the next card takes their place. Nothing
            // new appears in between, as the prototype has it.
            <div className={styles.grade}>
              <button
                type="button"
                className={cx(
                  styles.wrong,
                  outcome === 'wrong' && styles.gradePicked,
                  outcome === 'correct' && styles.gradePassed,
                )}
                disabled={outcome !== undefined}
                onClick={() => {
                  void answer(false);
                }}
              >
                {t('session.didntKnow')}
              </button>
              <button
                type="button"
                className={cx(
                  styles.right,
                  outcome === 'correct' && styles.gradePicked,
                  outcome === 'wrong' && styles.gradePassed,
                )}
                disabled={outcome !== undefined}
                onClick={() => {
                  void answer(true);
                }}
              >
                {t('session.knewIt')}
              </button>
            </div>
          )}
        </div>
      </div>

      <p className="sr-only" role="status" aria-live="polite">
        {[
          outcome === 'correct' ? t('session.correct') : outcome === 'wrong' ? t('session.wrong') : '',
          tip === undefined ? '' : t(`tip.${tip}`),
        ]
          .filter((line) => line !== '')
          .join(' ')}
      </p>

      {state.celebrate && (
        // The prototype's small gold-edged card: it fades out on its own and
        // never blocks the next card.
        <div className={styles.celebrate} aria-live="polite">
          <div className={styles.celebrateCard}>
            <span className={styles.celebrateKicker}>{t('session.mastered')}</span>
            <span className={styles.celebrateWord}>{state.celebrate.headword}</span>
          </div>
        </div>
      )}

      {detailOpen && (
        <Sheet
          onClose={() => {
            setDetailOpen(false);
          }}
        >
          <WordDetail
            wordId={card.word.id}
            embedded
            onClose={() => {
              setDetailOpen(false);
            }}
          />
        </Sheet>
      )}

      {noteOpen && (
        <NoteSheet
          initial={card.word.progress?.memo ?? ''}
          headword={card.word.headword}
          onSave={(memo) => {
            void saveNote(memo);
            setNoteOpen(false);
          }}
          onClose={() => {
            setNoteOpen(false);
          }}
        />
      )}
    </main>
  );
}

/**
 * How long an answered card stays when a tip is said about it (the first
 * miss, the first answer kept as practice): long enough to read one
 * sentence, against 0.7 s for a right answer and 1.6 s for a wrong one.
 */
const TIP_READ_MS = 3200;

/**
 * The tip a session card shows, if any (features/learn): the line under the
 * first flips in this device's first sessions (M2), at the first miss (M3),
 * at the first answer kept as practice (M8). This session is numbered once
 * it is running, which is what "the first two sessions" counts.
 */
function useCardTip(state: SessionState, flipped: boolean): TipId | undefined {
  const learn = useLearn();
  const tips = learn.on ? learn.tips : null;
  const running = state.status === 'running' && tips !== null;
  const [session, setSession] = useState<number | undefined>(undefined);
  const numbered = useRef(false);
  useEffect(() => {
    if (!running || numbered.current) return;
    numbered.current = true;
    void startTipSession().then((number) => {
      if (number !== undefined) setSession(number);
    });
  }, [running]);

  const { card, outcome, practised } = state;
  const flipCard = card !== undefined && !isChoice(card.type) && !isTyped(card.type);
  const pick =
    card === undefined || session === undefined
      ? undefined
      : pickTip(
          'card',
          {
            today: localDay(),
            session,
            wants: {
              firstGrade: flipCard && flipped && outcome === undefined,
              firstMiss: outcome === 'wrong',
              firstPracticeOnly: outcome === 'correct' && practised,
            },
          },
          tips,
        );
  return useHeldTip(pick, `${card?.key ?? ''}:${outcome ?? 'asking'}`);
}

/** How far a finger must travel before it counts as a swipe. */
const SWIPE_THRESHOLD = 70;

/**
 * Grades by swipe, following the finger with a slight rotation the way the
 * prototype does. Pointer events cover touch, pen and mouse alike.
 */
function SwipeArea({
  enabled,
  onLeft,
  onRight,
  children,
}: {
  enabled: boolean;
  onLeft: () => void;
  onRight: () => void;
  children: React.ReactNode;
}): React.JSX.Element {
  const [dx, setDx] = useState(0);
  const start = useRef<number | undefined>(undefined);

  const end = (): void => {
    if (start.current === undefined) return;
    const travelled = dx;
    start.current = undefined;
    setDx(0);
    if (Math.abs(travelled) < SWIPE_THRESHOLD) return;
    if (travelled < 0) onLeft();
    else onRight();
  };

  return (
    <div
      className={styles.stage}
      style={dx === 0 ? undefined : { transform: `translateX(${dx}px) rotate(${dx / 28}deg)` }}
      onPointerDown={(event) => {
        if (!enabled) return;
        start.current = event.clientX;
      }}
      onPointerMove={(event) => {
        if (!enabled || start.current === undefined) return;
        setDx(event.clientX - start.current);
      }}
      onPointerUp={end}
      onPointerCancel={end}
    >
      {children}
    </div>
  );
}

/** "Flashcard", "Multiple choice" — the prototype's own names for a type. */
/**
 * The question this card is asking, in a few words.
 *
 * One line per card type, because "what am I being asked to do" is the
 * first thing to know and each type asks something different.
 */
function askFor(type: CardType): string {
  const asks: Record<CardType, string> = {
    classic: t('session.askFlash'),
    reverse: t('session.askRecall'),
    mc: t('session.askChoice'),
    spell: t('session.askSpell'),
    cloze: t('session.askCloze'),
    audio: t('session.askListen'),
  };
  return asks[type];
}

function typeLabel(type: CardType): string {
  const labels: Record<CardType, string> = {
    classic: t('session.typeClassic'),
    reverse: t('session.typeReverse'),
    mc: t('session.typeMc'),
    spell: t('session.typeSpell'),
    cloze: t('session.typeCloze'),
    audio: t('session.typeAudio'),
  };
  return labels[type];
}
